import { chromium } from 'playwright';import fs from 'fs';import path from 'path';
const BASE='https://www.statesideqm.com',THEME='158900125851',key=process.env.KEY,label=process.env.LABEL,route=process.env.ROUTE,OUT='sep18-sg-fast-root-verify-'+key;fs.mkdirSync(path.join(OUT,'screenshots'),{recursive:true});
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});await c.addInitScript(()=>{window.__sqLcp=0;try{new PerformanceObserver(l=>{for(const e of l.getEntries())window.__sqLcp=Math.max(window.__sqLcp,e.startTime||0)}).observe({type:'largest-contentful-paint',buffered:true})}catch{}});
const p=await c.newPage();p.setDefaultNavigationTimeout(70000);const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);let resp=null,error=null;
try{resp=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(900)}catch(e){error=String(e?.message||e)}
const initial=await p.evaluate(({label,route,themeId})=>{const n=performance.getEntriesByType('navigation')[0],rs=performance.getEntriesByType('resource'),f=performance.getEntriesByName('first-contentful-paint')[0];const cards=[...document.querySelectorAll('[data-sqsg-view] a.sqsg-card')].map(a=>({label:(a.querySelector('strong')?.textContent||'').trim(),meta:(a.querySelector('small')?.textContent||'').trim(),shell:a.dataset.sqFastRootShell||'',href:a.getAttribute('href')||''}));const productReq=rs.filter(r=>/\/collections\/[^/]+\/products\.json/.test(r.name)).map(r=>({url:r.name,start:Math.round(r.startTime),duration:Math.round(r.duration)}));return{label,route,theme:{id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')},ttfbMs:Math.round(n?.responseStart||0),dclMs:Math.round(n?.domContentLoadedEventEnd||0),loadMs:Math.round(n?.loadEventEnd||0),fcpMs:Math.round(f?.startTime||0),lcpMs:Math.round(window.__sqLcp||0),resources:rs.length,transferBytes:rs.reduce((s,r)=>s+(r.transferSize||0),0),domNodes:document.getElementsByTagName('*').length,scripts:document.scripts.length,images:document.images.length,cards,productReqBeforeLoad:productReq.filter(x=>x.start<(n?.loadEventEnd||0)),productReqAll:productReq,previewOk:String(window.Shopify?.theme?.id||'')===themeId}}, {label,route,themeId:THEME});
await p.screenshot({path:path.join(OUT,'screenshots','initial.png'),fullPage:false});
await p.waitForTimeout(8500);
const settled=await p.evaluate(()=>{const n=performance.getEntriesByType('navigation')[0],rs=performance.getEntriesByType('resource'),cards=[...document.querySelectorAll('[data-sqsg-view] a.sqsg-card')].map(a=>({label:(a.querySelector('strong')?.textContent||'').trim(),meta:(a.querySelector('small')?.textContent||'').trim(),shell:a.dataset.sqFastRootShell||'',href:a.getAttribute('href')||'',itemCount:a.dataset.sqItemCount||''}));const productReq=rs.filter(r=>/\/collections\/[^/]+\/products\.json/.test(r.name)).map(r=>({url:r.name,start:Math.round(r.startTime),duration:Math.round(r.duration)}));return{cards,cardCount:cards.length,productReq,productReqBeforeLoad:productReq.filter(x=>x.start<(n?.loadEventEnd||0)).length,productReqAfterLoad:productReq.filter(x=>x.start>=(n?.loadEventEnd||0)).length,transferBytes:rs.reduce((s,r)=>s+(r.transferSize||0),0),resources:rs.length,viewData:(()=>{const v=document.querySelector('[data-sqsg-view]');return v?[...v.attributes].filter(a=>a.name.startsWith('data-')).reduce((o,a)=>(o[a.name]=a.value,o),{}):{}})()}});await p.screenshot({path:path.join(OUT,'screenshots','settled.png'),fullPage:false});const out={httpStatus:resp?.status()??null,error,initial,settled};fs.writeFileSync(path.join(OUT,'result.json'),JSON.stringify(out,null,2));console.log('SGFASTROOT',JSON.stringify({...out,initialKB:Math.round((initial.transferBytes||0)/1024),settledKB:Math.round((settled.transferBytes||0)/1024)}));if(out.httpStatus!==200||!initial.previewOk||error)process.exitCode=2;await c.close();await b.close();